function initLazyLoad(){if("IntersectionObserver"in window){const t=document.querySelectorAll("img[data-src]"),e=new IntersectionObserver((a,r)=>{a.forEach(a=>{a.isIntersecting&&(a.target.src=a.target.dataset.src,a.target.removeAttribute("data-src"),a.target.classList.add("loaded"),r.unobserve(a.target))})},{rootMargin:"50px"});t.forEach(t=>e.observe(t))}else document.querySelectorAll("img[data-src]").forEach(t=>{t.src=t.dataset.src,t.removeAttribute("data-src"),t.classList.add("loaded")})}function reloadLazyLoad(){initLazyLoad()}function debounce(t,e){let a;return function(...r){clearTimeout(a),a=setTimeout(()=>t(...r),e)}}function getOptimizedImageUrl(t){return t&&!t.includes("data:")&&t}function prefetchResource(t,e="prefetch"){const a=document.createElement("link");a.rel=e,a.href=t,document.head.appendChild(a)}function prefetchNextPage(){const t=document.querySelector('a[href*="page="]');t&&prefetchResource(t.href,"prefetch")}function logPerformanceMetrics(){if(window.performance&&window.performance.timing){const t=window.performance.timing;console.log("📊 Performance Metrics:"),console.log(`⏱️ Page Load Time: ${t.loadEventEnd-t.navigationStart}ms`),console.log(`📡 Connect Time: ${t.responseEnd-t.requestStart}ms`),console.log(`🎨 Render Time: ${t.domComplete-t.domLoading}ms`)}}function optimizeForMobile(){window.matchMedia("(max-width: 768px)").matches&&document.body.classList.add("is-mobile")}document.addEventListener("DOMContentLoaded",initLazyLoad),window.addEventListener("load",()=>{setTimeout(logPerformanceMetrics,0)}),document.addEventListener("DOMContentLoaded",optimizeForMobile);